  "d.1reld25": "OMBOTE ONENE",
  "d.1rqtgty": "Omuriro worelegana u kara konyima yokutonda omuviri na ongoye.",
  "d.1rrapdk": "Ehi ri wire pombunda yeraka, pokati ko 68 degrees pombunda nokupita ko 2 degrees ouwa.",
  "d.1sbj4x1": "Ouzito 9.81 m/s2 (1 g).",
  "d.1slb8sf": "Epandi LOADOUT li pe omiviri 3 (STANDARD PLATING, REINFORCED PLATING, BULWARK PLATING).",
  "d.1tjhupz": "orunyo rombaroro yene ya Orion-81 (ozoruvanga zovakwao ku zi tarwa)",
